  --popover: 220 12% 20%;

  --popover-foreground: 220 10% 85%;

  --popover-border: 220 12% 28%;

  --primary: 220 40% 85%;

  --primary-foreground: 220 15% 15%;

  --secondary: 220 10% 25%;

  --secondary-foreground: 220 10% 85%;

  --muted: 220 8% 22%;

  --muted-foreground: 220 6% 65%;

  --accent: 220 8% 26%;

  --accent-foreground: 220 10% 85%;

  --destructive: 0 65% 30%;

  --destructive-foreground: 0 10% 90%;

  --input: 220 12% 35%;
  --ring: 220 40% 85%;
