    subcategories: ["Laptops", "Phones", "Tablets", "Electronics Accessories", "Other Electronics"]
  },
  "Textbooks": {
    subcategories: ["Physical Books", "Ebooks", "Math & Science", "Humanities", "Business", "Engineering", "Other Subjects"]
